Estimate the area under $y=x^2+3$ from $x=0$ to $x=2$ using four left-endpoint rectangles. State whether this is an overestimate or underestimate.
[tikz]
\begin{tikzpicture}[x=2cm,y=0.65cm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\draw[black] (0,0) rectangle (0.5,3);
\draw[black] (0.5,0) rectangle (1,3.25);
\draw[black] (1,0) rectangle (1.5,4);
\draw[black] (1.5,0) rectangle (2,5.25);
\draw[black,->] (0,0)--(2.3,0) node[right] {$x$};
\draw[black,->] (0,0)--(0,8) node[above] {$y$};
\draw[black,thick,domain=0:2,samples=50] plot (\x,{\x*\x+3});
\foreach \x in {0.5,1,1.5,2} {\draw[black] (\x,0.1)--(\x,-0.1);\path (\x,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\path (0,0) node[below left,font=\fontsize{8.5}{10}\selectfont] {$0$};
\path (1,7.5) node {$y=x^2+3$};
\end{tikzpicture}
[/tikz]

